const enabled = msg.payload === true;
flow.set('envases_dbs_local_enabled', enabled);
node.status({fill:enabled?'green':'grey',shape:'dot',text:enabled?'envío local activo':'envío local pausado'});
return {payload:{evento:enabled?'ESPEJO_LOCAL_ACTIVADO':'ESPEJO_LOCAL_PAUSADO'}};

if (flow.get('envases_dbs_local_enabled') !== true) return null;
const bad = (reason) => {
  const now = Date.now();
  const last = flow.get('envases_dbs_local_error_at') || 0;
  if (now - last < 60000) return null;
  flow.set('envases_dbs_local_error_at', now);
  return [null,{payload:{evento:'ESPEJO_LOCAL_CONFIG_ERROR',motivo:reason}}];
};
const base = String(env.get('DISAL_LOCAL_API_BASE_URL') || '').trim().replace(/\/+$/,'');
const key = String(env.get('DISAL_LOCAL_ENVASES_INTEGRATION_KEY') || '');
const productionBase = String(env.get('DISAL_API_BASE_URL') || '').trim().replace(/\/+$/,'');
const productionKey = String(env.get('DISAL_ENVASES_INTEGRATION_KEY') || '');
if (!/^https?:\/\/[^/?#]+\/api$/i.test(base)) return bad('URL local inválida; debe terminar en /api');
if (/^https?:\/\/(localhost|127(?:\.\d+){3}|0\.0\.0\.0)(?::\d+)?\/api$/i.test(base)) return bad('Usar la IP de la PC, no localhost de la VM');
if (base.toLowerCase() === productionBase.toLowerCase()) return bad('La URL local coincide con producción');
if (key.length < 32) return bad('Falta la clave de la integración local');
if (productionKey && key === productionKey) return bad('La clave local debe ser independiente');
const batch = msg.payload;
if (!batch || batch.source !== 'NODE_RED_ENVASES' || batch.schemaVersion !== 1 ||
    !Array.isArray(batch.maquinas) || batch.maquinas.length !== 1 ||
    typeof batch.maquinas[0].machine_ip !== 'string') return bad('Lote DBS inesperado');
return [{machine_ip:batch.maquinas[0].machine_ip,
  method:'POST',url:base + '/plants/ENVASES/telemetry/injection-machines',
  headers:{'Content-Type':'application/json','X-Node-Red-Key':key},payload:batch},null];

let body = msg.payload || {};
if (typeof body === 'string') { try { body = JSON.parse(body); } catch { body = {}; } }
const ip = msg.machine_ip || null;
if ((msg.statusCode === 200 || msg.statusCode === 201) && body.accepted === 1 && !body.rejected)
  return {payload:{evento:'ESPEJO_LOCAL_ACEPTADO',ip,persistido_en_influx:body.persisted === true}};
const details = Array.isArray(body.message) ? body.message : typeof body.message === 'string' ? [body.message] : [];
return {payload:{evento:'ESPEJO_LOCAL_ERROR_API',ip,status:msg.statusCode || null,
  validacion:details.slice(0,5).map(value=>String(value).slice(0,160))}};
